// Supplied Curro Serengeti 2027 PDFs. Requirements are not claimed as stocked products.
function curroHref(grade){return '#schools?school=curro-serengeti'+(grade?'&grade='+grade+'&intent=quote':'')}
function curroGradeCards(){return `<section class="school-grade-section school-grade-overview"><div class="wrap"><a class="text-link school-change" href="#schools">Change school</a><div class="school-grade-heading"><div><span class="eyebrow">Curro Serengeti · 2027</span><h2>Select your grade</h2></div></div><div class="school-grade-grid">${Object.keys(curroLists).map(g=>`<a class="school-grade-card" href="${curroHref(g)}"><div class="school-grade-card-top"><h3>Grade ${g}</h3><span>2027 list</span></div><span aria-hidden="true">→</span></a>`).join('')}</div></div></section>`}
function curroSource(grade){return 'school-lists/curro-serengeti-grade-'+grade+'-2027.pdf'}
function curroRequirements(grade,selected=[]){const data=curroLists[grade],counts={...data.general},sources={};Object.keys(counts).forEach(k=>sources[k]=['General requirements']);for(const subject of selected){for(const [k,q]of Object.entries(data.subjects[subject]||{})){counts[k]=(counts[k]||0)+q;(sources[k]||=[]).push(subject)}}const lines=Object.entries(counts).map(([k,q])=>({id:`curro-${grade}-core-${k}`,name:curroNames[k],quantity:q,unit:k==='2'?'Pack of 10':k==='10'?'Pack of 3 or 4':'Each',source:sources[k].join(', '),optional:false}));for(const subject of selected){(data.extras[subject]||[]).forEach((name,i)=>{const match=name.match(/^(\d+) × /);lines.push({id:`curro-${grade}-extra-${subject==='Visual Arts'?'art':subject==='Creative Arts'?'creative':'egd'}-${i}`,name:name.replace(/^\d+ × /,''),quantity:match?Number(match[1]):subject==='Engineering Graphics and Design'?1:null,unit:'Each / set as specified',source:subject,optional:/optional/i.test(name)})})}return lines}
// Register source-only requirements outside the retail catalogue, so quote baskets survive refresh.
for(const grade of Object.keys(curroLists)){for(const line of curroRequirements(grade,[...Object.keys(curroLists[grade].subjects),...Object.keys(curroLists[grade].extras)])){if(!retiredProducts.some(p=>p.id===line.id))retiredProducts.push({id:line.id,schoolRequirement:true,category:'books',name:line.name,summary:`Curro Serengeti · Grade ${grade} · 2027 school requirement; specification and supply to be confirmed`,unit:line.unit,brand:'To be confirmed',specs:{School:'Curro Serengeti',Grade:grade,Year:'2027'}})}}
function curroListSection(){const grade=schoolSelectedGrade();return `<section class="school-grade-section curro-detail"><div class="wrap"><a class="school-change text-link" href="${curroHref()}">← Curro Serengeti · All grades</a><span class="eyebrow">Curro Serengeti · 2027</span><h1>Grade ${esc(grade)} stationery list</h1><p><a class="text-link" href="${curroSource(grade)}" target="_blank" rel="noopener">View original school list (PDF)</a></p><form id="curro-form"><div class="curro-controls"><div class="field"><label for="curro-grade">Grade</label><select id="curro-grade">${Object.keys(curroLists).map(g=>`<option ${g===grade?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label for="curro-learners">Learners with the same subjects</label><input id="curro-learners" type="number" min="1" max="9999" value="1" required></div></div><fieldset class="curro-subjects"><legend>Select the learner’s subjects</legend><p>General stationery is included. Choose only the subjects taken by this learner. Changing subjects or learner count resets item quantities.</p>${[...new Set([...Object.keys(curroLists[grade].subjects),...Object.keys(curroLists[grade].extras)])].map(subject=>`<label><input type="checkbox" name="curro-subject" value="${esc(subject)}"> ${esc(subject)}</label>`).join('')}</fieldset>${grade==='12'?'<p class="school-pack-note">English: the school prefers reusing the Grade 10–11 books. Exclude books already owned.</p>':''}<div id="curro-rows"></div><p class="school-summary-help">These are school specifications, not confirmed product matches. Prices and availability will be confirmed by quotation. For art items without a stated quantity, enter the required number of units or sets. EGD pack contents are listed in the original PDF; books are ordered through the EGD teacher.</p><div class="curro-actions"><strong id="curro-count" aria-live="polite"></strong><button type="submit" class="btn dark">Add selected items to quote</button></div><p id="curro-error" class="error" role="alert"></p></form></div></section>`}
function bindCurroLists(){const form=$('#curro-form');if(!form)return;const grade=schoolSelectedGrade();let current=[];const selected=()=>[...form.querySelectorAll('[name="curro-subject"]:checked')].map(x=>x.value);function render(){const learners=$('#curro-learners').valueAsNumber;current=curroRequirements(grade,selected());$('#curro-rows').innerHTML=`<div class="school-list-table-wrap"><table class="curro-table"><thead><tr><th scope="col">Include · Item</th><th scope="col">Quantity</th><th scope="col">Unit</th></tr></thead><tbody>${current.map(line=>`<tr><td><label><input type="checkbox" data-curro-include="${line.id}" ${line.quantity&&!line.optional?'checked':''}> <strong>${esc(line.name)}</strong></label><small>${esc(line.source)}${line.optional?' · Optional':''}</small></td><td><input data-curro-qty="${line.id}" aria-label="Quantity for ${esc(line.name)}" type="number" min="1" max="999999" step="1" ${line.quantity?`value="${line.quantity*(Number.isInteger(learners)?learners:1)}"`:'placeholder="Enter quantity"'}></td><td>${esc(line.unit)}</td></tr>`).join('')}</tbody></table></div>`;count()}
function count(){$('#curro-count').textContent=form.querySelectorAll('[data-curro-include]:checked').length+' item lines selected'}
$('#curro-grade').onchange=e=>location.hash=curroHref(e.target.value);form.querySelectorAll('[name="curro-subject"]').forEach(x=>x.onchange=render);$('#curro-learners').oninput=render;form.addEventListener('change',count);form.onsubmit=e=>{e.preventDefault();const error=$('#curro-error');error.textContent='';if(!selected().length){error.textContent='Select the learner’s subjects before adding the list.';return}const lines=current.filter(l=>form.querySelector(`[data-curro-include="${l.id}"]`).checked).map(l=>({...l,quantity:form.querySelector(`[data-curro-qty="${l.id}"]`).valueAsNumber}));if(!lines.length||lines.some(l=>!Number.isInteger(l.quantity)||l.quantity<1||l.quantity>999999)){error.textContent='Select at least one item and enter a whole quantity for every included item.';return}if(items.length+lines.length>250){error.textContent='The quote basket allows up to 250 item lines.';return}for(const line of lines)items.push({productId:line.id,description:`Curro Serengeti · Grade ${grade} · 2027 — ${line.name}. Subjects: ${line.source}. School specification; supply to be confirmed.`,quantity:line.quantity,unit:line.unit});formData.buyerType='School / education';updateCount();location.hash='#basket?mode=quote&buyer=schools'};render()}
